"""Convert real LVGL PPM captures to PNG and an offline clickable review file.
Only standard library. No font files or device data are distributed.
"""
from pathlib import Path
import struct,zlib,base64,json,html
r=Path(__file__).resolve().parents[2]
out=r/'docs/calm-menu';out.mkdir(parents=True,exist_ok=True)
images={}
def readppm(path):
 data=path.read_bytes();magic,wh,maxv,rgb=data.split(b'\n',3);assert magic==b'P6' and maxv==b'255'
 w,h=map(int,wh.split());assert len(rgb)==w*h*3;return w,h,rgb
def png(w,h,rgb):
 def chunk(kind,payload):return struct.pack('>I',len(payload))+kind+payload+struct.pack('>I',zlib.crc32(kind+payload)&0xffffffff)
 raw=b''.join(b'\0'+rgb[y*w*3:(y+1)*w*3] for y in range(h))
 return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,2,0,0,0))+chunk(b'IDAT',zlib.compress(raw,9))+chunk(b'IEND',b'')
for p in sorted((r/'artifacts/calm-ui').glob('*.ppm')):
 w,h,rgb=readppm(p);assert (w,h)==(480,800);data=png(w,h,rgb);(out/(p.stem+'.png')).write_bytes(data);images[p.stem]=data
before=r/'artifacts/before-ui/home-no-data.ppm'
if before.exists():
 w,h,rgb=readppm(before);(out/'home-before.png').write_bytes(png(w,h,rgb))
def montage(names,path):
 W=24+len(names)*504;H=848;data=bytearray(bytes([8,13,15])*W*H)
 for i,name in enumerate(names):
  p=before if name=='before' else r/'artifacts/calm-ui'/(name+'.ppm');w,h,rgb=readppm(p)
  for y in range(h):
   a=((y+24)*W+24+i*504)*3;data[a:a+w*3]=rgb[y*w*3:(y+1)*w*3]
 (out/path).write_bytes(png(W,H,data))
montage(['home-no-data','equipment','fuel-no-data','settings'],'overview.png')
if before.exists():montage(['before','home-no-data'],'before-after.png')
labels={'home-no-data':'Главная','equipment':'Оборудование','fuel-no-data':'Топливо','settings':'Настройки','connections':'Подключения','wifi':'Wi-Fi','service':'Сервис','storage':'microSD','diagnostics':'Диагностика','home-assistant':'Home Assistant','electric':'Электрокотёл','electric-editor':'Пороги электрокотла','electric-setpoints-fixture':'Электрокотёл с тестовыми порогами','about':'О панели','pairing-header-fixture':'Код перед часами (пример)','home-values-fixture':'Главная с тестовыми значениями','fuel-values-fixture':'Топливо с тестовыми значениями','home-stale-fixture':'Устаревшие значения (пример)','forget-confirm':'Подтверждение удаления сети','storage-confirm-fixture':'Подтверждение стирания (пример)','wifi-results-fixture':'Список сетей (пример)','credentials-fixture':'Ввод пароля (пример)','display':'Экран','bluetooth':'Bluetooth','temperature-no-data':'Температура подробно','boiler':'Бойлер','diesel':'Дизельный отопитель','fuel-heater':'Подогрев топлива'}
labels.update({'supply-no-data':'Подача', 'return-no-data':'Обратка', 'supply-values-fixture':'Подача (пример)', 'return-values-fixture':'Обратка (пример)', 'tank-no-data':'Топливо в баке', 'outlet-no-data':'Топливо на выходе', 'tank-values-fixture':'Топливо в баке (пример)', 'outlet-values-fixture':'Топливо на выходе (пример)'})
encoded={k:'data:image/png;base64,'+base64.b64encode(v).decode('ascii') for k,v in images.items()}
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Котельная — новый интерфейс 480×800</title><style>
:root{color-scheme:dark;font-family:system-ui,Arial,sans-serif;background:#101719;color:#eff5f3}*{box-sizing:border-box}body{margin:0;padding:30px}h1{font-size:26px;line-height:1.25;margin:0 0 10px}p{color:#a1b3b5;line-height:1.6;max-width:760px}header{max-width:1100px;margin:auto auto 28px}.tag{color:#76d6c3;font-size:12px;letter-spacing:.1em}main{max-width:1100px;margin:auto;display:grid;grid-template-columns:minmax(280px,480px) minmax(220px,1fr);gap:38px;align-items:start}.panel{position:relative;width:100%;aspect-ratio:3/5;border-radius:20px;overflow:hidden;box-shadow:0 0 0 8px #080d0f}.panel img{display:block;width:100%;height:100%;pointer-events:none}.hotspot{position:absolute;background:transparent;border:0;margin:0;cursor:pointer;border-radius:14px}.hotspot:hover,.hotspot:focus-visible{outline:2px solid #76d6c3;background:#76d6c310}aside{position:sticky;top:20px}nav{display:grid;gap:8px}nav button,.outside{background:#1b2528;border:1px solid #304044;color:#eff5f3;padding:11px 15px;text-align:left;border-radius:10px;font:inherit;cursor:pointer}nav button.active{border-color:#76d6c3;color:#76d6c3}.note{font-size:14px;padding:14px;border-left:3px solid #76d6c3;background:#1b2528}.subnav{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:20px}.subnav button{font-size:13px}details{margin-top:24px}summary{cursor:pointer;padding:10px 0}.caption{color:#e7bb78;min-height:24px;font-size:13px}.outside{display:block;margin-top:14px;width:100%}@media(max-width:750px){body{padding:18px}main{grid-template-columns:1fr;gap:26px}.panel{max-width:480px;margin:auto}aside{position:static}nav{grid-template-columns:1fr 1fr}}
</style><header><span class="tag">ВАРИАНТ ДЛЯ ПРОСМОТРА · НЕ УСТАНОВЛЕН</span><h1>Меньше информации на одном экране</h1><p>Это снимки, отрисованные настоящим LVGL 8.3.11 из изменённого кода панели. Нажимайте строки и карточки или листайте влево/вправо. Области переходов здесь — только просмотр: сеть, настройки и устройство не изменяются.</p></header><main><div><div class="panel" id="panel"><img id="screen" alt="Экран панели"><div id="links"></div></div><button class="outside" id="back">Назад в просмотре</button><p class="caption" id="fixture"></p></div><aside><h2 id="title">Главная</h2><nav id="roots"></nav><p class="note">В карточках «Теплоноситель» и «Топливо» нажатие на строку открывает историю выбранной температуры. Нажатие на канистру открывает уровень топлива.</p><div class="subnav" id="subnav"></div><details><summary>Состояния для проверки</summary><nav id="states"></nav><p>Все значения, адреса, сети, код 123456 и сведения о карте на этих снимках — из тестового стенда, не с вашей панели.</p></details></aside></main><script>
const images=IMAGES,labels=LABELS;const roots=['home-no-data','equipment','fuel-no-data','settings'];let current=roots[0],history=[];const $=id=>document.getElementById(id);
function show(name,push=true){if(!images[name])return;if(push&&current!==name)history.push(current);current=name;$('screen').src=images[name];$('screen').alt=labels[name]||name;$('title').textContent=labels[name]||name;$('fixture').textContent=name.includes('fixture')?'Тестовый сценарий. Это не показания реального устройства.':'Просмотр макета, без соединения с устройством.';document.querySelectorAll('[data-screen]').forEach(b=>b.classList.toggle('active',b.dataset.screen===name));$('links').replaceChildren();for(const [x,y,w,h,to] of zones(name)){const b=document.createElement('button');b.className='hotspot';Object.assign(b.style,{left:x/480*100+'%',top:y/800*100+'%',width:w/480*100+'%',height:h/800*100+'%'});b.title=labels[to]||to;b.ariaLabel=b.title;b.onclick=()=>to==='@back'?$('back').click():show(to);$('links').append(b);}}
function zones(n){let z=[];if(!n.startsWith('home-')&&n!=='electric-editor')z.push([350,18,106,56,'home-no-data']);const parents={connections:'settings',wifi:'connections','home-assistant':'connections',bluetooth:'connections',display:'settings',service:'settings',storage:'service',diagnostics:'service',about:'service','pairing-fixture':'settings',electric:'equipment','electric-setpoints-fixture':'equipment',boiler:'equipment',diesel:'equipment','fuel-heater':'equipment'};if(parents[n])z.push([16,18,56,56,parents[n]]);if(n.startsWith('home-')){for(const i of [0,1])z.push([24+i*224,112,208,300,'temperature-no-data']);const suffix=n==='home-values-fixture'?'values-fixture':'no-data';z.push([25,483,206,125,'supply-'+suffix],[25,608,206,125,'return-'+suffix],[249,435,206,48,'fuel-'+suffix],[249,483,206,125,'tank-'+suffix],[249,608,206,125,'outlet-'+suffix]);}if(n==='electric'||n==='electric-setpoints-fixture')z.push([24,510,432,58,'electric-editor']);if(n==='electric-editor')z.push([18,390,144,56,'@back']);if(n==='equipment')['boiler','electric','diesel','fuel-heater'].forEach((v,i)=>z.push([24,116+i*143,432,122,v]));if(n==='fuel-no-data'||n==='fuel-values-fixture'||n==='fuel-heater'){const y=n==='fuel-heater'?357:157;const suffix=n==='fuel-values-fixture'?'values-fixture':'no-data';z.push([25,y,206,125,'tank-'+suffix],[241,y,206,125,'outlet-'+suffix]);if(n!=='fuel-heater')z.push([24,648,432,100,'fuel-heater']);}if(n==='settings')['connections','display','service'].forEach((v,i)=>z.push([24,116+i*143,432,122,v]));if(n==='connections') ['wifi','bluetooth','home-assistant'].forEach((v,i)=>z.push([24,116+i*143,432,122,v]));if(n==='service')['storage','diagnostics','about'].forEach((v,i)=>z.push([24,116+i*143,432,122,v]));if(n==='temperature-no-data'||n.startsWith('supply-')||n.startsWith('return-')||n.startsWith('tank-')||n.startsWith('outlet-'))z.push([24,684,432,60,'@back']);return z.filter(v=>images[v[4]]||v[4]==='@back');}
function button(name,holder){if(!images[name])return;const b=document.createElement('button');b.textContent=labels[name]||name;b.dataset.screen=name;b.onclick=()=>show(name);$(holder).append(b);}roots.forEach(n=>button(n,'roots'));['connections','wifi','home-assistant','display','bluetooth','service','storage','diagnostics','about','temperature-no-data'].forEach(n=>button(n,'subnav'));Object.keys(images).filter(n=>n.includes('fixture')||n==='forget-confirm').forEach(n=>button(n,'states'));
$('back').onclick=()=>{const n=history.pop();if(n)show(n,false)};let x=0;$('panel').addEventListener('pointerdown',e=>x=e.clientX);$('panel').addEventListener('pointerup',e=>{if(Math.abs(e.clientX-x)>70){const i=roots.indexOf(current);if(i>=0)show(roots[(i+(e.clientX<x?1:3))%4]);}});document.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){const i=Math.max(0,roots.indexOf(current));show(roots[(i+(e.key==='ArrowRight'?1:3))%4]);}});show(current,false);
</script></html>'''
page=page.replace('IMAGES',json.dumps(encoded,ensure_ascii=False)).replace('LABELS',json.dumps(labels,ensure_ascii=False))
(out/'preview.html').write_text(page,encoding='utf-8')
print('PNG previews:',len(images),'offline HTML bytes:',len(page.encode()))
